Ext._define('estagio.comissao.IntegrantesComissaoGrid', {
    extend: 'core.RestfulGrid',

    restWindow: 'estagio.comissao.IntegrantesComissaoWindow',

    configOrderToolBar: ['add', 'edit', 'remove', 'doMove','doMoveDown', '-', 'search'],

    getDoMoveAction: function(cfg) {
        if(!this._domoveup)
            this._domoveup = Ext._create('Ext.Button', {
                text: 'Acima',
                iconCls: 'icon-gep icon-up',
                scope: this,
                handler: function() {
                    this._move('up')
                },
            });

        return this._domoveup;
    },  

    getDoMoveDownAction: function(cfg) {
        if(!this._domovedown)
            this._domovedown = Ext._create('Ext.Button', {
                text: 'Abaixo',
                iconCls: 'icon-gep icon-down',
                scope: this,
                handler: function() {
                    this._move('down')
                },
            });

        return this._domovedown;
    },

    _move: function(direction){
        var selection = this.getSelectionModel().getSelected();

        if (selection){
            var rest = this.factoryRestful();
            var mask = new Ext.LoadMask(this.getEl(), {msg: 'Criando publicação...'});
            mask.show();
            rest.doRequest(
                rest.getRoute('move_integrante', false, 'POST', {
                    scope: this,
                    params: {
                        pk: selection.id,
                        direction: direction
                    },
                    callback: function() {
                        mask.hide();
                        mask = undefined;
                    },
                    success: function(xhr) {
                        var rst = Ext.decode(xhr.responseText);

                        if(rst.success) {
                            this.getStore().reload();
                        }
                        else
                            Ext.Msg.show({
                                title: 'Movendo Integrante',
                                icon: Ext.Msg.ERROR,
                                buttons: Ext.Msg.OK,
                                msg: rst.message
                            });
                    },
                    failure: function(xhr) {
                        Ext.Msg.show({
                            title: 'Movendo Integrante',
                            icon: Ext.Msg.ERROR,
                            buttons: Ext.Msg.OK,
                            msg: 'Recurso indisponível no momento.'
                        });
                    },
                })
            );

        }else{
            Ext.Msg.show({
                'title': 'Integrantes da Comissão',
                'msg': 'Primeiro selecione o item que deseja mover.',
                'icon': Ext.Msg.WARNING,
                'buttons': Ext.Msg.OK
            });
        }

    },

    getColumnModel: function() {
        if(!this._columnModel)
            this._columnModel = Ext._create(
                'Ext.grid.ColumnModel',
                [
                    Ext._create('Ext.grid.RowNumberer'),
                    {header: 'Descricao', dataIndex: 'unicode', id: 'autoExpandColumn', hidden: true},
                    {header: 'Integrante', dataIndex: 'servidor_id_unicode', width: 300},
                    {header: 'Função', dataIndex: 'tipo_participante_display', width: 150},
                    {header: 'Impedimento', dataIndex: 'impedimento_display', width: 100},
                ]
            );

        return this._columnModel;
    }
});

core.RestfulGrid.register(
    'estagio.comissao.IntegrantesComissaoRestful',
    'estagio.comissao.IntegrantesComissaoGrid'
);

